#include <stdio.h>
#include <stdlib.h>

int main() {
    int rows = 2, cols = 3;

    // 1. Allocate array of row pointers
    int **matrix = (int **)malloc(rows * sizeof(int *));

    // 2. Allocate memory for each row
    for (int i = 0; i < rows; i++) {
        matrix[i] = (int *)malloc(cols * sizeof(int));
    }

    // 3. Use the array
    matrix[0][1] = 99;
    printf("matrix[0][1] = %d\n", matrix[0][1]);

    return 0;
}
